import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = () => {
  const [latestEntry, setLatestEntry] = useState(null);

  useEffect(() => {
    fetchLatestEntry();
    const interval = setInterval(fetchLatestEntry, 1000); // Fast poll for live feel
    return () => clearInterval(interval);
  }, []);

  async function fetchLatestEntry() {
    // 1. Get the very last record added to the table
    // We order by 'created_at' descending to get the newest one
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("created_at", { ascending: false }) 
      .limit(1);

    if (error) console.log("Error:", error);
    
    // 2. If we found a record, set it as the current status
    if (data && data.length > 0) {
      setLatestEntry(data[0]);
    } else {
      setLatestEntry(null);
    }
  }

  // LOGIC: If we have a latest entry, we assume the slot is OCCUPIED by that car.
  // (You can add logic here: if(latestEntry.status === 'exited') setOccupied(false))
  const isOccupied = latestEntry ? true : false;

  return (
    <main className="dashboard-root">
      
      {/* STATS */}
      <section className="stats-container">
        <div className="stat-card green">
          <div className="stat-title">Available</div>
          <div className="stat-value">{isOccupied ? 0 : 1}</div>
        </div>

        <div className="stat-card red">
          <div className="stat-title">Occupied</div>
          <div className="stat-value">{isOccupied ? 1 : 0}</div>
        </div>
      </section>

      {/* SINGLE SLOT DISPLAY */}
      <section className="layout-section">
        <div className="layout-header">Live Parking Spot Status</div>
        
        <div className="single-slot-container">
           {/* Pass the 'latestEntry' data to the card so we can show the Time/Plate */}
           <SlotCard 
              slotData={latestEntry} 
              isOccupied={isOccupied} 
           />
        </div>
      </section>

    </main>
  );
};

export default UserDashboard;
